{
  "description": "Contratti di locazione",
  "baseAnalyzerId": "prebuilt-document",
  "config": {
    "estimateFieldSourceAndConfidence": false
  },
  "fieldSchema": {
    "fields": {
      "Locatore": {
        "type": "string",
        "method": "extract",
        "description": "Nome del proprietario, nel preambolo dopo \"Il locatore\".",
        "estimateSourceAndConfidence": true
      },
      "Canone": {
        "type": "number",
        "method": "extract",
        "description": "Canone mensile in euro, nell'articolo sul corrispettivo.",
        "estimateSourceAndConfidence": true
      },
      "Decorrenza": {
        "type": "date",
        "method": "extract",
        "description": "Data di inizio della locazione, nell'articolo sulla durata.",
        "estimateSourceAndConfidence": true
      },
      "Deposito": {
        "type": "number",
        "method": "extract",
        "description": "Importo del deposito cauzionale.",
        "estimateSourceAndConfidence": true
      },
      "TipoContratto": {
        "type": "string",
        "method": "classify",
        "enum": [
          "4+4",
          "3+2",
          "transitorio",
          "altro"
        ],
        "description": "Categoria del documento in base al contenuto."
      },
      "Righe": {
        "type": "array",
        "description": "Una voce per ogni riga della tabella.",
        "items": {
          "type": "object",
          "properties": {
            "Descrizione": {
              "type": "string"
            },
            "Quantita": {
              "type": "number"
            },
            "Importo": {
              "type": "number"
            }
          }
        }
      }
    }
  }
}
